Reset(dtpHomeDtfInicio_3);
Reset(cmbHomeBloco_3);
Reset(cmbHomeAeroporto_3);
Reset(dtpHomeDtfTermino_3);
Reset(cmbApontStatus);
Reset(cmbHomeLocal);
Reset(cmbHomeItem);
Reset(cmbHomeLocal);
Reset(cmbHomeItem);
Reset(cmbHomeSubitem);
Reset(txtLimitApont);
UpdateContext({var_directDetInsp: 0})

Set(
    varIDhtmlCriado,
    'Criar-HTML'.Run(
        HtmlText3.HtmlText,
        "INSP-PISTA-" & varIATAUser & "-" & Now()
    ).idhtml
);
Launch(
    Substitute(
        LookUp(
            Documentos,
            ID = varIDhtmlCriado,
            Miniatura.Large
        ),
        "thumbnail",
        "pdf"
    )
)

UpdateContext(
    {
        var_visibleFilterApontForm: true,
        var_acaoItem: "normalizar",
        var_itemView: false
    }
)

Remove(
    'AIRPORTNOW - FAUNA RELACIONAMENTO',
    ThisItem
);
Notify(
    "Operação realizada com sucesso!",
    NotificationType.Success,
