)

"<style>
    body {
        font-family: Arial;
        font-size: 10px;
        margin: 0;
    }
    .header {
        display: flex;
        justify-content: space-between;
        align-items: center;
        margin-bottom: 10px;
        padding: 10px;
    }
    .title {
        color: #6600ed;
        font-size: 18px;
        font-weight: bold;
    }
    .logo {
        height: 40px;
    }
    table {
        width: 100%;
        border-collapse: collapse;
        margin-bottom: 20px;
    }
    thead {
        display: table-header-group;
    }
    th, td {
        border: 1px solid #ddd;
        padding: 6px;
        text-align: left;
    }
    th {
        background-color: #f2f2f2;
    }
    td {
        font-size: 10px;
    }
    tr:nth-child(even) {
        background-color: #f9f9f9;
    }
    .footer {
        font-size: 10px;
        text-align: right;
        padding: 5px 10px;
        border-top: 1px solid #ccc;
    }
    .col-protocolo {
        width: 130;
        word-break: break-word;
    }
    .col-criado {
        width: 100;
        word-break: break-word;
    }
</style>

<div class='header'>
    <div class='title'>Relatório de Inspeção de Pista</div>
</div>

<table>
    <thead>
        <tr>
            <th class='col-protocolo'>Protocolo</th>
            <th>Criado em</th>
            <th>Local</th>
            <th>Item</th>
            <th>Subitem</th>
            <th>Status</th>
            <th>Descrição</th>
        </tr>
    </thead>
    <tbody>" &

Concat(
If(
    var_directDetInsp > 0,
    Filter(
        '7.4.1-tbl_InspPistaItens',
        IdInsp = var_directDetInsp
    ),
    FirstN(
        Sort(
            Filter(
                '7.4.1-tbl_InspPistaItens',
                IsBlank(cmbHomeAeroporto_3.Selected.Value) || StartsWith(
                    Aeroporto,
                    Text(cmbHomeAeroporto_3.Selected.Value)
                ),
                IsBlank(cmbHomeBloco_3.Selected.Value) || StartsWith(
                    Bloco,
                    Text(cmbHomeBloco_3.Selected.Value)
                ),
                IsBlank(cmbApontStatus.Selected.Value) || StartsWith(
                    Status,
                    cmbApontStatus.Selected.Value
                ),
                IsBlank(cmbHomeLocal.Selected.Value) || StartsWith(
                    Local,
                    cmbHomeLocal.Selected.Value
                ),
                IsBlank(cmbHomeItem.Selected.Value) || StartsWith(
                    Item,
                    cmbHomeItem.Selected.Value
                ),
                IsBlank(cmbHomeSubitem.Selected.Value) || StartsWith(
                    sIten,
                    cmbHomeSubitem.Selected.Value
                ),
                Criado >= dtpHomeDtfInicio_3.SelectedDate && Criado <= DateAdd(
                    dtpHomeDtfTermino_3.SelectedDate,
                    1
                )
            ),
            ID,
            SortOrder.Descending
        ),
        Value(txtLimitApont.Text)
    )
),
"<tr><td class='col-protocolo'>" & LookUp(colAeros, Aeroporto = cmbHomeAeroporto_3.Selected.Value).IATA & "-INSP-PISTA-" & ID & "</td>" &
"<td class='col-criado'>" & Text(Criado, "[$-pt-BR]dd/mm/yyyy HH:mm") & "</td>" &
"<td>" & Local & "</td>" &
"<td>" & Item & "</td>" &
"<td>" & sIten & "</td>" &
"<td>" & Status & "</td>" &
"<td>" &
Switch(
    sIten,
    "Colisão com dano", LookUp('AIRPORTNOW - Colisões/Quase-Colisão/Avistamento', ID = ID_fauna).'Descrição da ocorrência',
    "Colisão sem dano", LookUp('AIRPORTNOW - Colisões/Quase-Colisão/Avistamento', ID = ID_fauna).'Descrição da ocorrência',
    "Quase colisão", LookUp('AIRPORTNOW - Colisões/Quase-Colisão/Avistamento', ID = ID_fauna).'Descrição da ocorrência',
    "Avistamento", LookUp('AIRPORTNOW - Colisões/Quase-Colisão/Avistamento', ID = ID_fauna).'Descrição da ocorrência',
    "Presença de fauna", LookUp('Presença de Fauna', ID = ID_fauna).'Descrição do evento/observação',
    "Foco de atração de fauna", LookUp('Formulário de Focos (Atrativos e Vulnerabilidade)', ID = ID_fauna).Observações,
    "Vulnerabilidade em proteções físicas", LookUp('Formulário de Focos (Atrativos e Vulnerabilidade)', ID = ID_fauna).Observações,
    Descricao
) & "</td></tr>"
) &

"</tbody></table>
<div class='footer'>Gerado em: " & Text(Now(), "[$-pt-BR]dd/mm/yyyy hh:mm") & "</div>"
